/* K1 — the K1-EFI partition, format 2 (see k1_uklad.h). */
#include "k1_uklad.h"
#include "k1_bajty.h"

#include <string.h>

#include "monocypher.h"

#define NAGLOWEK "# GRUB Environment Block\n"
#define UWAGA "# WARNING: Do not edit this file by tools other than grub-editenv!!!\n" /* as grub-editenv writes it */
#define SUMA_OFF 496u
#define MIN_OFF (64u << 10)

/* [a, a+an) and [b, b+bn) overlap */
static int zachodza(uint64_t a, uint64_t an, uint64_t b, uint64_t bn)
{
    return a < b + bn && b < a + an;
}

static int miejsce(uint64_t off, uint64_t n, uint64_t fat)
{
    return off % 512 == 0 && off >= MIN_OFF && off <= fat && n <= fat - off;
}

int k1_uklad_czytaj(const uint8_t *buf, uint64_t partycja, struct k1_uklad *u)
{
    uint8_t suma[16];
    size_t i;
    memset(u, 0, sizeof *u);
    if (memcmp(buf, "K1U1", 4) != 0 || buf[4] != 1 || buf[5] != 0 || buf[6] != 0 || buf[7] != 0)
        goto zle;
    for (i = 48; i < SUMA_OFF; i++)
        if (buf[i] != 0)
            goto zle;
    crypto_blake2b(suma, sizeof suma, buf, SUMA_OFF);
    if (memcmp(suma, buf + SUMA_OFF, sizeof suma) != 0)
        goto zle;
    u->fat_bajty = k1_c64(buf + 8);
    u->grubenv_off = k1_c64(buf + 16);
    u->slot_bajty = k1_c64(buf + 24);
    u->slot_off[0] = k1_c64(buf + 32);
    u->slot_off[1] = k1_c64(buf + 40);
    if (u->fat_bajty == 0 || u->fat_bajty > partycja || u->slot_bajty < K1_SLOT_MIN ||
        u->slot_bajty > K1_SLOT_MAKS || u->slot_bajty % K1_SLOT_MIB != 0 ||
        !miejsce(u->grubenv_off, K1_GRUBENV_BAJTY, u->fat_bajty) || !miejsce(u->slot_off[0], u->slot_bajty, u->fat_bajty) ||
        !miejsce(u->slot_off[1], u->slot_bajty, u->fat_bajty) ||
        zachodza(u->slot_off[0], u->slot_bajty, u->slot_off[1], u->slot_bajty) ||
        zachodza(u->grubenv_off, K1_GRUBENV_BAJTY, u->slot_off[0], u->slot_bajty) ||
        zachodza(u->grubenv_off, K1_GRUBENV_BAJTY, u->slot_off[1], u->slot_bajty) ||
        zachodza(K1_UKLAD_OFF, K1_UKLAD_BAJTY, u->grubenv_off, K1_GRUBENV_BAJTY))
        goto zle;
    return 0;
zle:
    memset(u, 0, sizeof *u);
    return -1;
}

void k1_uklad_zbuduj(const struct k1_uklad *u, uint8_t *buf)
{
    memset(buf, 0, K1_UKLAD_BAJTY);
    memcpy(buf, "K1U1", 4);
    buf[4] = 1;
    k1_z64(buf + 8, u->fat_bajty);
    k1_z64(buf + 16, u->grubenv_off);
    k1_z64(buf + 24, u->slot_bajty);
    k1_z64(buf + 32, u->slot_off[0]);
    k1_z64(buf + 40, u->slot_off[1]);
    crypto_blake2b(buf + SUMA_OFF, 16, buf, SUMA_OFF);
}

int k1_slot_nr(char slot)
{
    return slot == 'a' ? 0 : slot == 'b' ? 1 : -1;
}

static const char *const NAZWY[4] = { "k1_slot", "k1_start", "k1_nowy", "k1_proba" };

static char *pole(struct k1_grubenv *e, int i)
{
    return i == 0 ? &e->slot : i == 1 ? &e->start : i == 2 ? &e->nowy : &e->proba;
}

int k1_grubenv_czytaj(const uint8_t *buf, struct k1_grubenv *e)
{
    size_t p = sizeof NAGLOWEK - 1, i;
    int widziane = 0;
    memset(e, 0, sizeof *e);
    if (memcmp(buf, NAGLOWEK, p) != 0)
        return -1;
    while (p < K1_GRUBENV_BAJTY) {
        size_t start = p, rown = 0, n;
        int k;
        if (buf[p] == '#') { /* a comment line, or the padding up to the end */
            while (p < K1_GRUBENV_BAJTY && buf[p] != '\n')
                p++;
            if (p == K1_GRUBENV_BAJTY) {
                for (i = start; i < K1_GRUBENV_BAJTY; i++)
                    if (buf[i] != '#')
                        goto zle;
                return 0;
            }
            p++;
            continue;
        }
        while (p < K1_GRUBENV_BAJTY && buf[p] != '\n') {
            if (buf[p] == '=' && rown == 0)
                rown = p;
            if (buf[p] == 0 || buf[p] == '\\')
                goto zle; /* no NUL; escapes are never written by us or by GRUB for these values */
            p++;
        }
        if (p == K1_GRUBENV_BAJTY || rown == 0 || rown == start)
            goto zle;
        n = rown - start;
        for (k = 0; k < 4; k++) {
            if (strlen(NAZWY[k]) != n || memcmp(buf + start, NAZWY[k], n) != 0)
                continue;
            if ((widziane & 1 << k) != 0)
                goto zle; /* twice */
            widziane |= 1 << k;
            if (p - rown == 2 && (buf[rown + 1] == 'a' || buf[rown + 1] == 'b'))
                *pole(e, k) = (char)buf[rown + 1];
            else if (p - rown != 1)
                goto zle;
        }
        p++; /* '\n' */
    }
    return 0; /* the last line ended exactly at the end: no padding */
zle:
    memset(e, 0, sizeof *e);
    return -1;
}

void k1_grubenv_zbuduj(const struct k1_grubenv *e, uint8_t *buf)
{
    size_t p = sizeof NAGLOWEK - 1;
    int k;
    memset(buf, '#', K1_GRUBENV_BAJTY);
    memcpy(buf, NAGLOWEK, p);
    memcpy(buf + p, UWAGA, sizeof UWAGA - 1);
    p += sizeof UWAGA - 1;
    for (k = 0; k < 4; k++) {
        char v = *pole((struct k1_grubenv *)e, k);
        size_t n = strlen(NAZWY[k]);
        memcpy(buf + p, NAZWY[k], n);
        p += n;
        buf[p++] = '=';
        if (v == 'a' || v == 'b')
            buf[p++] = (uint8_t)v;
        buf[p++] = '\n';
    }
}

enum k1_ab k1_ab_decyzja(const struct k1_grubenv *e, int ten_sam)
{
    if (k1_slot_nr(e->proba) < 0)
        return K1_AB_NIC;
    if (e->start != e->proba)
        return K1_AB_NIEUDANA;
    return ten_sam ? K1_AB_POTWIERDZ : K1_AB_NIC;
}
